// Command server runs the Link Shelf HTTP service.
//
// It opens the SQLite database at linkshelf.db in the current
// working directory, applies the schema, registers the API and
// static routes on http.DefaultServeMux, and listens on :8080.
package main

import (
	"database/sql"
	"log"
	"net/http"

	"linkshelf/internal/api"
	"linkshelf/internal/store"

	_ "github.com/mattn/go-sqlite3"
)

func main() {
	db, err := sql.Open("sqlite3", "linkshelf.db")
	if err != nil {
		log.Fatalf("open db: %v", err)
	}
	if err := store.InitSchema(db); err != nil {
		log.Fatalf("init schema: %v", err)
	}
	store.DB = db

	// Register all Link Shelf routes on the default mux. The api
	// package owns the route table; main.go owns process bootstrap.
	api.RegisterRoutes(http.DefaultServeMux)

	log.Println("listening on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatalf("listen: %v", err)
	}
}

