:root {
  --bg: #f7f7f9;
  --card-bg: #ffffff;
  --text: #1f2330;
  --muted: #6b7280;
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --border: #e5e7eb;
  --danger: #dc2626;
  --danger-hover: #b91c1c;
  --radius: 6px;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
  --gap: 12px;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

h1,
h2 {
  margin: 0 0 var(--gap) 0;
  color: var(--text);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
}

h2 {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

#app,
main,
.container {
  max-width: 640px;
  margin: 32px auto;
  padding: 24px;
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}

form {
  display: flex;
  flex-direction: column;
  gap: var(--gap);
  margin-bottom: 24px;
}

label {
  display: flex;
  flex-direction: column;
  gap: 4px;
  font-size: 0.875rem;
  color: var(--muted);
  font-weight: 500;
}

input[type="text"],
input[type="url"] {
  width: 100%;
  padding: 8px 10px;
  font-size: 1rem;
  color: var(--text);
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

input[type="text"]:focus,
input[type="url"]:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);
}

button,
input[type="submit"] {
  align-self: flex-start;
  padding: 8px 16px;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  background: var(--primary);
  border: 1px solid var(--primary);
  border-radius: var(--radius);
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

button:hover,
input[type="submit"]:hover {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}

button:disabled,
input[type="submit"]:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

ul#links {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

ul#links li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gap);
  padding: 10px 12px;
  background: #fff;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  transition: box-shadow 0.15s ease;
}

ul#links li:hover {
  box-shadow: var(--shadow);
}

ul#links li a {
  color: var(--primary);
  text-decoration: none;
  font-weight: 500;
  word-break: break-all;
  flex: 1 1 auto;
}

ul#links li a:hover {
  text-decoration: underline;
}

ul#links li button,
ul#links li .delete {
  flex: 0 0 auto;
  padding: 4px 10px;
  font-size: 0.85rem;
  background: transparent;
  color: var(--danger);
  border: 1px solid var(--danger);
  border-radius: var(--radius);
  cursor: pointer;
}

ul#links li button:hover,
ul#links li .delete:hover {
  background: var(--danger);
  color: #fff;
  border-color: var(--danger-hover);
}

.empty,
#empty {
  color: var(--muted);
  text-align: center;
  padding: 16px 0;
  font-style: italic;
}

.error,
#error {
  color: var(--danger);
  font-size: 0.875rem;
  margin-top: 4px;
  min-height: 1.25em;
}

